 import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, color, fract, sin, dot, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh } = THREE;

  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find((i) => i.role === 'headline') ?? items[0];

  const cardW = 1.6;
  const cardH = 1.0;

  const cardGeometry = new PlaneGeometry(cardW, cardH);

  // engineered gradient surface with subtle grain
  const t = uv().y;
  const surfaceNode = color(surface);
  const inkNode = color(ink);
  const gradient = mix(surfaceNode, inkNode, smoothstep(0.0, 1.0, t));

  const noise = ctx.tier === 'T0'
    ? gradient
    : gradient.add(
        fract(sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453))
          .mul(0.05)
          .sub(0.025)
      );

  const backdropMaterial = new MeshBasicNodeMaterial({ colorNode: noise });
  const backdrop = new Mesh(cardGeometry, backdropMaterial);
  backdrop.position.z = -0.01;
  group.add(backdrop);

  // textured decorative plane
  const imageMaterial = new MeshBasicNodeMaterial({ transparent: true });
  const imageMesh = new Mesh(cardGeometry, imageMaterial);
  group.add(imageMesh);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (!imageMesh.parent) return;
      tex.colorSpace = THREE.SRGBColorSpace;
      imageMaterial.map = tex;
      imageMaterial.needsUpdate = true;
    });
  }

  // small accent marker
  const accentGeometry = new PlaneGeometry(0.32, 0.04);
  const accentMaterial = new MeshBasicNodeMaterial({ colorNode: color(accent) });
  const accentLine = new Mesh(accentGeometry, accentMaterial);
  accentLine.position.set(-cardW * 0.5 + 0.2, -cardH * 0.38, 0.02);
  group.add(accentLine);

  // headline text
  if (textItem) {
    const label = ctx.fontAtlas.createText(textItem.text ?? textItem.content ?? 'Pricing 1', {
      fontSize: textItem.typography?.fontSize ?? 39,
      color: paper,
      align: 'left',
    });
    label.position.set(-cardW * 0.45, cardH * 0.18, 0.03);
    label.scale.setScalar(0.003);
    group.add(label);
  }

  // weighted entrance
  const entrance = gsap.timeline({ defaults: { ease: 'power3.out' } });
  entrance.from(group.scale, { x: 0, y: 0, z: 0, duration: 0.6, ease: 'power3.out' });
  entrance.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.4, ease: 'power2.out' }, '>');
  entrance.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' }, '>');

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    entrance.kill();
    cardGeometry.dispose();
    backdropMaterial.dispose();
    imageMaterial.dispose();
    accentGeometry.dispose();
    accentMaterial.dispose();
    if (imageMaterial.map) imageMaterial.map.dispose();
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
